export const LCCP_CREST_BASE64 = "";
export const LCCP_BANNER_BASE64 = "";

export function base64ToUint8Array(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(base64, "base64");
  }
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function getLccpCrestBuffer(): Uint8Array {
  return base64ToUint8Array(LCCP_CREST_BASE64);
}

export function getLccpBannerBuffer(): Uint8Array {
  return base64ToUint8Array(LCCP_BANNER_BASE64);
}

export const LCCP_PAASCU_BASE64 = "";

export const LCCP_CREST_DATA_URI = `data:image/png;base64,${LCCP_CREST_BASE64}`;
export const LCCP_BANNER_DATA_URI = `data:image/jpeg;base64,${LCCP_BANNER_BASE64}`;
export const LCCP_PAASCU_DATA_URI = `data:image/png;base64,${LCCP_PAASCU_BASE64}`;

export function getLccpPaascuBuffer(): Uint8Array {
  return base64ToUint8Array(LCCP_PAASCU_BASE64);
}

export function dataUriToUint8Array(dataUri?: string): Uint8Array | null {
  if (!dataUri) return null;
  const commaIdx = dataUri.indexOf(",");
  const rawBase64 = commaIdx >= 0 ? dataUri.slice(commaIdx + 1) : dataUri;
  if (!rawBase64 || rawBase64.length < 16) return null;
  try {
    return base64ToUint8Array(rawBase64);
  } catch {
    return null;
  }
}
